  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    dist_list = case['distances']

    dist_dict = {}
    for a, b, d in dist_list:
        key = tuple(sorted((a, b)))
        dist_dict[key] = d

    edges = []
    for a, b, d in dist_list:
        if a < b:
            u, v = a, b
        else:
            u, v = b, a
        w = max(core_dist[a], core_dist[b], d)
        edges.append((w, u, v))

    edges.sort(key=lambda x: (x[0], x[1], x[2]))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst.append([u, v, w])
            total_weight += w
            if len(mst) == len(nodes) - 1:
                break

    if len(mst) != len(nodes) - 1:
        raise ValueError('Disconnected graph: MST cannot connect all nodes')

    return {
        'mst_edges': mst,
        'total_weight': total_weight
    }"
}
